static inline uint8_t bcd2bin(uint8_t val)
{
	return ((val >> 4) & 0xf) * 10 + (val & 0xf);
}

static inline uint8_t bin2bcd(uint8_t val)
{
	return ((val / 10) << 4) | (val % 10);
}

struct elog_header {
	uint32_t magic;
	uint8_t version;
	uint8_t header_size;
	uint8_t reserved[2];
} __packed;

struct event_header {
	uint8_t type;
	uint8_t length;
	uint8_t year;
	uint8_t month;
	uint8_t day;
	uint8_t hour;
	uint8_t minute;
	uint8_t second;
} __packed;

struct elog_ec_event {
	uint8_t event;
	uint8_t checksum;
} __packed;

struct elog_event_data_wake {
	uint8_t source;
	uint32_t instance;
} __packed;

struct elog_event_data_me_extended {
	uint8_t current_working_state;
	uint8_t operation_state;
	uint8_t operation_mode;
	uint8_t error_code;
	uint8_t progress_code;
	uint8_t current_pmevent;
	uint8_t current_state;
} __packed;

struct elog_event_mem_cache_update {
	uint8_t slot;
	uint8_t status;
} __packed;

union elog_event_cros_diag_log {
	uint8_t raw[3];
	struct {
		/* 5-bit type code, see ELOG_CROS_DIAG_TYPE_* above */
		uint8_t type	: ELOG_CROS_DIAG_LOG_TYPE_BITS;
		/* 3-bit result code, see ELOG_CROS_DIAG_RESULT_* above */
		uint8_t result	: ELOG_CROS_DIAG_LOG_RESULT_BITS;
		/*
		 * The running time of this diagnostics test item. If the
		 * running time exceeds the UINT16_MAX, it will be stored as
		 * UINT16_MAX instead.
		 */
		uint16_t time_s;
	} __packed;
} __packed;

struct elog_event_extended_event {
	uint8_t event_type;
	uint32_t event_complement;
} __packed;

struct xxh32_state {
	uint32_t total_len_32;
	uint32_t large_len;
	uint32_t v1;
	uint32_t v2;
	uint32_t v3;
	uint32_t v4;
	uint32_t mem32[4];
	uint32_t memsize;
};

struct xxh64_state {
	uint64_t total_len;
	uint64_t v1;
	uint64_t v2;
	uint64_t v3;
	uint64_t v4;
	uint64_t mem64[4];
	uint32_t memsize;
};

