import random
import struct
from typing import List

# Generator for arbitrary binary data buffers suitable for checksum/hash fuzzers.
# Strategy:
# - Produce varied lengths, including 0, small, typical MTU-like sizes, powers of two, odd/even lengths.
# - Include diverse byte patterns: all-zero, all-FF, incremental, alternating, random, repeated blocks.
# - Optionally prepend/append small paddings to exercise head skew and concatenation logic.
# - Keep size <= 4096 bytes.
# - Make output deterministic given the seed, but with variety across seeds.

MAX_OUT = 4096

def _pattern_all_zero(n: int) -> bytes:
    if n <= 0:
        return b""
    return b"\x00" * n

def _pattern_all_ff(n: int) -> bytes:
    if n <= 0:
        return b""
    return b"\xff" * n

def _pattern_incrementing(n: int, start: int = 0) -> bytes:
    if n <= 0:
        return b""
    return bytes(((start + i) & 0xFF) for i in range(n))

def _pattern_decrementing(n: int, start: int = 255) -> bytes:
    if n <= 0:
        return b""
    return bytes(((start - i) & 0xFF) for i in range(n))

def _pattern_alternating(n: int, a: int = 0x55, b: int = 0xAA) -> bytes:
    if n <= 0:
        return b""
    return bytes((a if (i & 1) == 0 else b) for i in range(n))

def _pattern_random(n: int, rnd: random.Random) -> bytes:
    if n <= 0:
        return b""
    # Python 3.10 Random.randbytes handles n==0, but guard against negatives.
    return rnd.randbytes(n)

def _pattern_repeated_block(n: int, block: bytes) -> bytes:
    if n <= 0:
        return b""
    if not block:
        return b""
    reps, rem = divmod(n, len(block))
    return block * reps + block[:rem]

def _choose_length(rnd: random.Random) -> int:
    candidates: List[int] = [
        0, 1, 2, 3, 4, 5, 7, 8, 9, 15, 16, 31, 32, 63, 64,
        127, 128, 255, 256, 511, 512, 1024, 1200, 1400, 1420, 1460, 1472, 1500,
        1536, 1792, 2048, 3072, 4096
    ]
    # Bias toward sizes <= 1500 since the ipchksum stub clamps around 1500 bytes.
    weights = [10 if x <= 1500 else 2 for x in candidates]
    # Also occasionally pick a random length up to 4096
    if rnd.random() < 0.4:
        return max(0, min(MAX_OUT, rnd.randint(0, MAX_OUT)))
    return rnd.choices(candidates, weights=weights, k=1)[0]

def _maybe_pad(data: bytes, rnd: random.Random) -> bytes:
    # Optionally add small prefix/suffix paddings (head skew in fuzzer may slice these away)
    if not data:
        return data
    prefix_len = 0
    suffix_len = 0
    if rnd.random() < 0.5:
        prefix_len = rnd.randint(0, min(8, max(0, MAX_OUT - len(data))))
    if rnd.random() < 0.5:
        suffix_len = rnd.randint(0, min(8, max(0, MAX_OUT - len(data) - prefix_len)))
    if prefix_len == 0 and suffix_len == 0:
        return data
    # Prefix and suffix use deterministic simple patterns
    prefix = _pattern_incrementing(prefix_len, start=rnd.randint(0, 255))
    suffix = _pattern_decrementing(suffix_len, start=rnd.randint(0, 255))
    return prefix + data + suffix

def _build_blocky(rnd: random.Random, total_len: int) -> bytes:
    # Build a buffer as concatenation of multiple subpatterns to diversify content
    if total_len <= 0:
        return b""
    out = bytearray()
    remain = total_len
    # Builders
    builders = []
    builders.append(lambda n: _pattern_random(n, rnd))
    builders.append(lambda n: _pattern_incrementing(n, start=rnd.randint(0, 255)))
    builders.append(lambda n: _pattern_alternating(n, a=rnd.randrange(256), b=rnd.randrange(256)))
    builders.append(lambda n: _pattern_all_zero(n))
    builders.append(lambda n: _pattern_all_ff(n))
    # Repeated block with a small motif
    motif_len = rnd.choice([1, 2, 3, 4, 5, 8, 16, 32])
    motif = _pattern_random(motif_len, rnd)
    builders.append(lambda n, m=motif: _pattern_repeated_block(n, m))

    # Choose number of segments
    segs = rnd.randint(1, 6)
    for i in range(segs):
        if i == segs - 1:
            seg_len = remain
        else:
            # Keep at least 1 byte for each remaining segment
            max_seg = remain - (segs - i - 1)
            if max_seg < 1:
                seg_len = 0
            else:
                seg_len = rnd.randint(1, max_seg)
        if seg_len <= 0:
            continue
        builder = rnd.choice(builders)
        out.extend(builder(seg_len))
        remain -= seg_len
        if remain <= 0:
            break
    return bytes(out)

def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    # Select a strategy
    strategy = rnd.random()

    n = _choose_length(rnd)

    if strategy < 0.2:
        # Pure random buffer of length n
        data = _pattern_random(n, rnd)
    elif strategy < 0.35:
        # Incrementing or decrementing
        if rnd.random() < 0.5:
            data = _pattern_incrementing(n, start=rnd.randrange(256))
        else:
            data = _pattern_decrementing(n, start=rnd.randrange(256))
    elif strategy < 0.5:
        # Alternating or repeated blocks
        if rnd.random() < 0.5:
            data = _pattern_alternating(n, a=rnd.randrange(256), b=rnd.randrange(256))
        else:
            block_len = rnd.choice([1, 2, 3, 4, 8, 16, 32])
            block = _pattern_random(block_len, rnd)
            data = _pattern_repeated_block(n, block)
    elif strategy < 0.7:
        # Edge-case constants
        choice = rnd.random()
        if choice < 0.34:
            data = _pattern_all_zero(n)
        elif choice < 0.67:
            data = _pattern_all_ff(n)
        else:
            # Mixed zero/FF halves to create strong transitions
            half = n // 2
            data = _pattern_all_zero(half) + _pattern_all_ff(n - half)
    else:
        # Blocky composed content
        data = _build_blocky(rnd, n)

    # Optional header to aid ipchksum_add parity tests when concatenated
    if rnd.random() < 0.3 and len(data) + 4 <= MAX_OUT:
        # Insert a small, self-describing 4-byte header: len (16-bit), parity byte, tag (unsigned byte)
        length16 = len(data) & 0xFFFF
        parity = len(data) & 1
        tag = rnd.choice([0x00, 0x55, 0xAA, 0xFF])
        header = struct.pack('<HBB', length16, parity, tag)
        data = header + data

    # Maybe add small paddings to exercise head skew behavior
    data = _maybe_pad(data, rnd)

    # Ensure final size bound
    if len(data) > MAX_OUT:
        data = data[:MAX_OUT]

    return data
